                <div><label><span><?= $escape($uiText('Language')) ?></span><select class="form-input" name="locale"><option value=""><?= $escape($uiText('Any language')) ?></option><?php foreach($languages as$language): ?><option value="<?= $escape($language['locale']) ?>"><?= $escape($language['native_name']?:$language['name']) ?></option><?php endforeach; ?></select></label><label><span><?= $escape($uiText('Required source key')) ?></span><input class="form-input" name="required_source_key" maxlength="191" placeholder="<?= $escape($uiText('Optional traceability requirement')) ?>"></label></div>
                <button class="btn bg-primary text-white" type="submit"><i data-lucide="plus"></i><?= $escape($uiText('Add evaluation')) ?></button>
            </form>
            <div class="sensecms-training-list is-scrollable"><?php if(!$evaluations): ?><div class="sensecms-training-empty"><?= $escape($uiText('No evaluation cases yet.')) ?></div><?php endif; ?><?php foreach($evaluations as$evaluation): ?><article><div><header><strong><?= $escape($evaluation['name']) ?></strong><span class="is-ready"><?= $escape($uiText('active')) ?></span></header><p><?= $escape(mb_strimwidth((string)$evaluation['question'],0,150,'…')) ?></p><small><?= $escape(!empty($evaluation['locale'])?strtoupper($evaluation['locale']):'Any language') ?> · by <?= $escape($evaluation['created_by_name']) ?></small></div><nav><form method="post" action="/ai/knowledge/training/evaluation/<?= (int)$evaluation['id'] ?>/delete"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><button type="submit" title="<?= $escape($uiText('Delete')) ?>"><i data-lucide="trash-2"></i></button></form></nav></article><?php endforeach; ?></div>
        </section>
    </div>
    <section class="card sensecms-training-locked"><div><span class="sensecms-section-icon is-ai"><i data-lucide="shield-check"></i></span><span><strong><?= $escape($uiText('Local preparation only')) ?></strong><p><?= $escape($uiText('Ready datasets can be validated and exported as immutable JSONL packages. Provider submission stays locked until Sense CMS can show a current price estimate and require a separate explicit confirmation.')) ?></p></span></div><button class="btn bg-default-150" type="button" disabled><i data-lucide="play"></i><?= $escape($uiText('Start paid fine-tuning')) ?></button><small><i data-lucide="circle-dollar-sign"></i><?= $escape($uiText('No provider API request or charge is made while preparing a package.')) ?></small></section>
    <?php if($jobs): ?><section class="card sensecms-training-panel"><div class="card-header"><div><h2 class="card-title"><?= $escape($uiText('Prepared packages')) ?></h2><p><?= $escape($uiText('Private, checksum-locked exports ready for offline review. Nothing has been submitted to a provider.')) ?></p></div><i data-lucide="package-check"></i></div><div class="sensecms-training-list"><?php foreach($jobs as$job): ?><article><div><header><strong><?= $escape($job['dataset_name']) ?></strong><span class="is-ready"><?= $escape($job['status']) ?></span></header><small><?= $escape($job['provider_name'].' · '.$job['base_model']) ?></small><p><?= (int)$job['example_count'] ?> examples · approximately <?= number_format((int)$job['estimated_tokens']) ?> tokens · checksum <?= $escape(substr((string)$job['dataset_checksum'],0,12)) ?>…</p></div><nav><a href="/ai/knowledge/training/job/<?= (int)$job['id'] ?>/download" title="<?= $escape($uiText('Download private JSONL package')) ?>"><i data-lucide="download"></i></a></nav></article><?php endforeach; ?></div></section><?php endif; ?>
